<script setup lang="ts">import {fmt} from '../utils/format';defineProps<{result:any}>();</script><template><dl class="inference-summary"><div><dt>所选轨迹 / 观测码</dt><dd>{{result.trace_count}}<em> / {{result.token_count}}</em></dd></div><div><dt>固定状态 / 观测字母表</dt><dd>{{result.states.length}}<em> / {{result.symbols.length}}</em></dd></div><div><dt>全部序列无约束 logL 和</dt><dd>{{fmt(result.total_log_likelihood,5)}}</dd></div><div><dt>边际拼接非法路径</dt><dd>{{result.illegal_marginal_paths}}</dd></div><div v-if="result.constrained_trace_count"><dt>标记轨迹 / 满足 / 冲突</dt><dd>{{result.constrained_trace_count}}<em> / {{result.constraint_satisfied_trace_count}} / {{result.constraint_conflict_trace_count}}</em></dd></div><div v-if="result.constraint_satisfied_trace_count"><dt>条件轨迹 logL 和（仅满足者）</dt><dd>{{fmt(result.conditional_total_log_likelihood,5)}}</dd></div><div v-if="result.constraint_conflict_trace_count"><dt>冲突轨迹无约束 logL 和</dt><dd>{{fmt(result.constraint_conflict_total_log_likelihood,5)}}</dd></div></dl><p v-if="result.constraint_conflicts?.length" class="copper conflict-line">首个无可行路径的时刻：<span v-for="c in result.constraint_conflicts" :key="c.id">{{c.reference}} 第{{c.first_infeasible_step}}步（{{c.stage==='model'?'模型层面':'观测层面'}}）</span></p></template>
